module fractional_n_pll (
    input wire clk_ref,       // Reference clock input (50 MHz)
    input wire reset,         // Active high reset
    input wire [3:0] frac_val, // Fractional value (0 to 15)
    output reg clk_out        // Output clock
);
    reg [3:0] counter;
    reg [3:0] div_counter;
    reg [3:0] frac_counter;

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            counter <= 0;
            div_counter <= 0;
            frac_counter <= 0;
            clk_out <= 0;
        end else begin
            counter <= counter + 1;

            if (counter == 1) begin  // Toggle every clock cycle
                clk_out <= ~clk_out;
                div_counter <= div_counter + 1;

                // Update fractional counter based on frac_val
                if (div_counter < frac_val) begin
                    frac_counter <= frac_counter + 1;
                end

                // Reset div_counter after reaching 7 (for 3.5)
                if (div_counter >= 7) begin
                    div_counter <= 0;
                end
            end
        end
    end
endmodule

