module pitch_detector (
    input clk,
    input reset,
    input [15:0] audio_signal,
    output reg [7:0] detected_pitch
);
    reg [15:0] previous_signal;
    reg [15:0] max_signal;
    reg [7:0] pitch_counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            detected_pitch <= 8'b0;
            pitch_counter <= 8'b0;
            max_signal <= 16'b0;
        end else begin
            if (audio_signal > max_signal) begin
                max_signal <= audio_signal;
                pitch_counter <= pitch_counter + 1;
            end else begin
                detected_pitch <= pitch_counter;
                max_signal <= 16'b0;
                pitch_counter <= 8'b0;
            end
        end
    end
endmodule

