module vco (
    input wire clk,
    input wire rst,
    input wire [3:0] control_voltage,
    output reg square_wave
);
    reg [23:0] counter;
    reg [23:0] frequency;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
            square_wave <= 0;
            frequency <= 24'd1000000; // Default frequency
        end else begin
            frequency <= 24'd1000000 >> control_voltage; // Adjust frequency based on control_voltage
            if (counter >= frequency) begin
                square_wave <= ~square_wave;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
