module ofdm_modulator (  
    input clk,  
    input rst_n,  
    input [7:0] data_in,  
    output reg [63:0] ofdm_out  
);  
    reg [7:0] data_reg [0:7];  
    reg [2:0] count;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            count <= 0;  
            ofdm_out <= 0;  
        end else if (count < 8) begin  
            data_reg[count] <= data_in;  
            count <= count + 1;  
        end else begin  
            // Simple IFFT emulation (for illustration purposes)  
            ofdm_out <= {data_reg[7], data_reg[6], data_reg[5], data_reg[4],  
                          data_reg[3], data_reg[2], data_reg[1], data_reg[0]};  
        end  
    end  
endmodule

