module uart_transmitter (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire send,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // Example: 50 MHz
    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_count;
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit
    reg [15:0] clk_div;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx <= 1;
            busy <= 0;
            bit_count <= 0;
            clk_div <= 0;
        end else begin
            if (send && !busy) begin
                shift_reg <= {1'b1, data_in, 1'b0}; // start bit + data + stop bit
                busy <= 1;
                bit_count <= 0;
                clk_div <= 0;
            end else if (busy) begin
                if (clk_div < BIT_PERIOD - 1) begin
                    clk_div <= clk_div + 1;
                end else begin
                    clk_div <= 0;
                    tx <= shift_reg[bit_count]; // Output the current bit
                    if (bit_count < 9) begin
                        bit_count <= bit_count + 1;
                    end else begin
                        busy <= 0; // Transmission complete
                    end
                end
            end
        end
    end
endmodule

