module crystal_oscillator (  
    input wire clk,  
    input wire reset,  
    input wire [3:0] freq_ctrl,  
    output reg out  
);  
    reg [31:0] counter;  
    reg [31:0] toggle_threshold;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            out <= 0;  
            toggle_threshold <= 0;  
        end else begin  
            if (toggle_threshold != 0) begin  
                if (counter >= toggle_threshold) begin  
                    out <= ~out;  
                    counter <= 0;  
                end else begin  
                    counter <= counter + 1;  
                end  
            end  
            toggle_threshold <= (16'hFFFF >> freq_ctrl);  
        end  
    end  
endmodule

