module ARQ_Controller(  
    input clk,  
    input reset,  
    input send_msg,  
    input ack_received,  
    output reg msg_sent,  
    output reg resend_msg  
);  
    reg [1:0] state;  
    parameter IDLE = 2'b00, WAIT_ACK = 2'b01, RESEND = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            msg_sent <= 0;  
            resend_msg <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send_msg) begin  
                        msg_sent <= 1;  
                        resend_msg <= 0;  
                        state <= WAIT_ACK;  
                    end  
                end  
                WAIT_ACK: begin  
                    if (ack_received) begin  
                        msg_sent <= 0;  
                        resend_msg <= 0;  
                        state <= IDLE;  
                    end else begin  
                        resend_msg <= 1;  
                        state <= RESEND;  
                    end  
                end  
                RESEND: begin  
                    msg_sent <= 1;  
                    resend_msg <= 0;  
                    state <= WAIT_ACK;  
                end  
            endcase  
        end  
    end  
endmodule

