module PID_Controller #(  
    parameter WIDTH = 16,  
    parameter Kp = 1,  
    parameter Ki = 1,  
    parameter Kd = 1  
)(
    input clk,  
    input reset,  
    input signed [WIDTH-1:0] error,  
    output reg signed [WIDTH-1:0] control_signal  
);  
    reg signed [WIDTH-1:0] integral;  
    reg signed [WIDTH-1:0] previous_error;  
    reg signed [WIDTH-1:0] derivative;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            integral <= 0;  
            previous_error <= 0;  
            control_signal <= 0;  
        end else begin  
            integral <= integral + error;  
            derivative <= error - previous_error;  
            control_signal <= (Kp * error) + (Ki * integral) + (Kd * derivative);  
            previous_error <= error;  
        end  
    end  
endmodule

